-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/bastok/Rivals.lua"]={["Path"]="scripts/quests/bastok/Rivals.lua",["SHA256"]="3acbda904ca5a0542d6671ba40f329e1df053c87a3588b32689b0b42afa0c194",["Text"]="-----------------------------------\n-- Rivals\n-----------------------------------\n-- Log ID: 1, Quest ID: 20\n-- Detzo : !pos 5.365 6.999 9.891 234\n-----------------------------------\nlocal bastokMinesID = zones[xi.zone.BASTOK_MINES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.RIVALS)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.WOLF_GORGET,\n    title    = xi.title.CONTEST_RIGGER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Detzo'] = quest:progressEvent(93),\n\n            onEventFinish =\n            {\n                [93] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Detzo'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.MYTHRIL_SALLET, 1 } }) then\n                        return quest:progressEvent(94)\n                    end\n                end,\n\n                onTrigger = quest:messageName(bastokMinesID.text.DETZO_RIVALS_DIALOG),\n            },\n\n            onEventFinish =\n            {\n                [94] = function(player, csid, option, npc)\n                    -- TODO: Since Detzo 'borrows' the Mythril Sallet, need to verify if\n                    -- a message is displayed for returning it (Obtained:, etc).\n\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Shady_Business.lua"]={["Path"]="scripts/quests/bastok/Shady_Business.lua",["SHA256"]="143f65c6bef641937f48a668baffbf904dad7e03c107411536a3451e73c05795",["Text"]="-----------------------------------\n-- Shady Business\n-----------------------------------\n-- Log ID: 1, Quest ID: 8\n-- Talib : !pos -101.133 4.649 28.803 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.SHADY_BUSINESS)\n\nquest.reward =\n{\n    gil = 350,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.BEAUTY_AND_THE_GALKA)\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Talib'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(90)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.CHUNK_OF_ZINC_ORE, 4 } }) then\n                        return quest:progressEvent(91)\n                    end\n                end,\n\n            },\n\n            onEventFinish =\n            {\n                [90] = function(player, csid, option, npc)\n                    -- We can complete the quest without accepting it, but quest will NOT get re-accepted after completed.\n                    if player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.SHADY_BUSINESS) == xi.questStatus.QUEST_AVAILABLE then\n                        quest:begin(player)\n                    end\n                end,\n\n                [91] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.NORG, 30)\n                        player:tradeComplete()\n                    end\n                end,\n\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Shoot_First_Ask_Questions_Later.lua"]={["Path"]="scripts/quests/bastok/Shoot_First_Ask_Questions_Later.lua",["SHA256"]="a863e331a1cf5794c60fd778df100fd86c816209da38c97c521742067ac6ec26",["Text"]="-----------------------------------\n-- Shoot First, Ask Questions Later\n-- Cid !pos -12 -12 1 237\n-- qm1 !pos -11 -19 -177 153\n-----------------------------------\nlocal metalworksID = zones[xi.zone.METALWORKS]\nlocal boyahdaTreeID = zones[xi.zone.THE_BOYAHDA_TREE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.SHOOT_FIRST_ASK_QUESTIONS_LATER)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.GUN_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.MARKSMANSHIP) / 10 >= 250 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Cid'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(795):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [795] = function(player, csid, option, npc)\n                    if\n                        player:hasItem(xi.item.GUN_OF_TRIALS) or\n                        npcUtil.giveItem(player, xi.item.GUN_OF_TRIALS)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Cid'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(799) -- complete\n                    else\n                        local hideReacquireMenuItem = (player:hasItem(xi.item.GUN_OF_TRIALS) or player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)) and 1 or 0\n                        return quest:event(796, hideReacquireMenuItem) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.GUN_OF_TRIALS, 1 } }) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(797) -- unfinished weapon\n                        else\n                            return quest:progressEvent(798) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [796] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        not player:hasItem(xi.item.GUN_OF_TRIALS)\n                    then\n                        npcUtil.giveItem(player, xi.item.GUN_OF_TRIALS)\n                    elseif option == 2 then\n                        player:delQuest(xi.questLog.BASTOK, xi.quest.id.bastok.SHOOT_FIRST_ASK_QUESTIONS_LATER)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [798] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [799] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.DETONATOR)\n                        player:messageSpecial(metalworksID.text.DETONATOR_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.THE_BOYAHDA_TREE] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, boyahdaTreeID.mob.BEET_LEAFHOPPER, { hide = 0 })\n                    then\n                        return quest:messageSpecial(boyahdaTreeID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Beet_Leafhopper'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Silence_of_the_Rams.lua"]={["Path"]="scripts/quests/bastok/Silence_of_the_Rams.lua",["SHA256"]="52a424dda70157943fb1552a211a7b8d80c57a1f1d84039e91ef140475cf4aab",["Text"]="-----------------------------------\n-- Silence of the Rams\n-----------------------------------\n-- Log ID: 1, Quest ID: 48\n-- Paujean : !pos -93.738 4.649 34.373 236\n-----------------------------------\nlocal portBastokID = zones[xi.zone.PORT_BASTOK]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.SILENCE_OF_THE_RAMS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.NORG,\n    item     = xi.item.PURPLE_BELT,\n    title    = xi.title.PURPLE_BELT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.NORG) >= 2\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Paujean'] = quest:progressEvent(195),\n\n            onEventFinish =\n            {\n                [195] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Paujean'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.LUMBERING_HORN, 1 }, { xi.item.RAMPAGING_HORN, 1 } }) then\n                        return quest:progressEvent(196)\n                    end\n                end,\n\n                onTrigger = quest:messageName(portBastokID.text.PAUJEAN_DIALOG_1),\n            },\n\n            onEventFinish =\n            {\n                [196] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Smoke_on_the_Mountain.lua"]={["Path"]="scripts/quests/bastok/Smoke_on_the_Mountain.lua",["SHA256"]="d5e22b834eb99d25ed7aa9497765c05d8551cd395670a36d1a522409ca2a3bce",["Text"]="-----------------------------------\n-- Smoke on the Mountain\n-----------------------------------\n-- Log ID: 1, Quest ID: 15\n-- Hungry Wolf : !pos -25.861 -11 -30.172 237\n-- Offa : !pos -281.628 -15.971 -140.607 235\n-- ??? (Campfire) !pos 461.841 -21.515 -580.105 107\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.SMOKE_ON_THE_MOUNTAIN)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 300,\n    title    = xi.title.HOT_DOG,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Hungry_Wolf'] = quest:progressEvent(428),\n\n            onEventFinish =\n            {\n                [428] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Hungry_Wolf'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.GALKAN_SAUSAGE, 1 } }) then\n                        return quest:progressEvent(429)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [429] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Offa'] = quest:event(222):oncePerZone(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Stamp_Hunt.lua"]={["Path"]="scripts/quests/bastok/Stamp_Hunt.lua",["SHA256"]="5373c2eb3521d891e2cc185c8c9e89d55b87201f96616a6eb263c298d8ef6939",["Text"]="-----------------------------------\n-- Stamp Hunt\n-----------------------------------\n-- Log ID: 1, Quest ID: 16\n-- Arawn         : !pos -121.492 -4.000 -123.923 235\n-- Pavel         : !pos -349.798 -10.002 -181.296 235\n-- Deadly Spider : !pos -57.601 -8 -55.944 234\n-- Tall Mountain : !pos 71 7 -7 234\n-- Elayne        : !pos -36.414 8 -1.465 237\n-- Romualdo      : !pos 135.035 -18.475 -37.419 237\n-- Ehrhard       : !pos -70.661 4.898 44.886 236\n-- Latifah       : !pos 51.241 7.499 -55.407 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.STAMP_HUNT)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item = xi.item.LEATHER_GORGET,\n    title = xi.title.STAMPEDER,\n}\n\nlocal function progressOnUnsetBit(player, bitValue, eventID)\n    if not quest:isVarBitsSet(player, 'Prog', bitValue) then\n        return quest:progressEvent(eventID)\n    end\nend\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Arawn'] = quest:progressEvent(225),\n\n            onEventFinish =\n            {\n                [225] = function(player, csid, option, npc)\n                    if npcUtil.giveKeyItem(player, xi.keyItem.STAMP_SHEET) then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Arawn'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:isVarBitsSet(player, 'Prog', 0, 1, 2, 3, 4, 5, 6) then\n                        return quest:progressEvent(226)\n                    end\n                end,\n            },\n\n            ['Pavel'] =\n            {\n                onTrigger = function(player, npc)\n                    return progressOnUnsetBit(player, 0, 227)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [226] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.STAMP_SHEET)\n                    end\n                end,\n\n                [227] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 0)\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Deadly_Spider'] =\n            {\n                onTrigger = function(player, npc)\n                    return progressOnUnsetBit(player, 1, 86)\n                end,\n            },\n\n            ['Tall_Mountain'] =\n            {\n                onTrigger = function(player, npc)\n                    return progressOnUnsetBit(player, 2, 85)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [85] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 2)\n                end,\n\n                [86] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Elayne'] =\n            {\n                onTrigger = function(player, npc)\n                    return progressOnUnsetBit(player, 3, 725)\n                end,\n            },\n\n            ['Romualdo'] =\n            {\n                onTrigger = function(player, npc)\n                    return progressOnUnsetBit(player, 4, 726)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [725] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 3)\n                end,\n\n                [726] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ehrhard'] =\n            {\n                onTrigger = function(player, npc)\n                    return progressOnUnsetBit(player, 5, 121)\n                end,\n            },\n\n            ['Latifah'] =\n            {\n                onTrigger = function(player, npc)\n                    return progressOnUnsetBit(player, 6, 120)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [120] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 6)\n                end,\n\n                [121] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Prog', 5)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Stardust.lua"]={["Path"]="scripts/quests/bastok/Stardust.lua",["SHA256"]="9f13f76209fd32d90a36347e7fcc3dd8d7586a227530fa2c822294c29a149231",["Text"]="-----------------------------------\n-- Stardust\n-----------------------------------\n-- Log ID: 1, Quest ID: 24\n-- Baldric : !pos -50.858 1.777 -31.141 237\n-- qm1     : !pos 238.524 2.661 -148.784 103\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.STARDUST)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 300,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Baldric'] = quest:progressEvent(554),\n\n            onEventFinish =\n            {\n                [554] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Baldric'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.PINCH_OF_VALKURM_SUNSAND, 1 } }) then\n                        return quest:progressEvent(555)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [555] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Drangord'] = quest:event(97),\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Baldric'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeMatches(trade, { { xi.item.PINCH_OF_VALKURM_SUNSAND, 1 } })\n                    then\n                        return quest:progressEvent(555)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        not quest:getMustZone(player)\n                    then\n                        return quest:progressEvent(554)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [554] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [555] = function(player, csid, option, npc)\n                    if\n                        not quest:getMustZone(player) and\n                        quest:complete(player)\n                    then\n                        player:tradeComplete()\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n\n}\n\nreturn quest\n"},["scripts/quests/bastok/Teak_Me_to_the_Stars.lua"]={["Path"]="scripts/quests/bastok/Teak_Me_to_the_Stars.lua",["SHA256"]="b741c6ec45936e0c203338e8b687a3bb546afe976b7f680e68a1e7990ddd28d4",["Text"]="-----------------------------------\n-- Teak Me to the Stars\n-----------------------------------\n-- Log ID: 1, Quest ID: 79\n-- Raibaht : !gotoid 17748012\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.TEAK_ME_TO_THE_STARS)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 2100,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Raibaht'] =\n            {\n                onTrigger = function(player, npc)\n                    local option = 0\n                    if player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_CALL_OF_THE_WYRMKING) then\n                        option = 2 -- additional dialogue regarding Crystal propulsion unit and hooded scientists as mentioned in cop wyrmking mission\n                    end\n\n                    return quest:progressEvent(864, 0, xi.item.GARHADA_TEAK_LUMBER, 0, 0, 0, 0, option)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [864] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Raibaht'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Cycle between event 871 and default 501\n                    return quest:event(871, 0, xi.item.GARHADA_TEAK_LUMBER):setPriority(10)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.GARHADA_TEAK_LUMBER, 1 } }) then\n                        return quest:event(865)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [865] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        xi.quest.setMustZone(player, xi.questLog.BASTOK, xi.quest.id.bastok.HYPER_ACTIVE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Bare_Bones.lua"]={["Path"]="scripts/quests/bastok/The_Bare_Bones.lua",["SHA256"]="d2a8c2fab392e34ecf459c6cd4c72a6971852851be7773beedc92cb44ff2477e",["Text"]="-----------------------------------\n-- The Bare Bones\n-----------------------------------\n-- Log ID: 1, Quest ID: 38\n-- Degenhard : !pos -175 2 -135 235\n-- Biggorf   : !pos -211.379 1.999 -142.024 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_BARE_BONES)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.MAP_OF_THE_DANGRUF_WADI,\n    fameArea = xi.fameArea.BASTOK,\n    fame = 20,\n    exp = 2000,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Degenhard'] = quest:progressEvent(256),\n\n            onEventFinish =\n            {\n                [256] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Biggorf'] = quest:progressEvent(257),\n\n            ['Degenhard'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.BONE_CHIP, 1 } }) then\n                        return quest:progressEvent(258)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [258] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Cold_Light_of_Day.lua"]={["Path"]="scripts/quests/bastok/The_Cold_Light_of_Day.lua",["SHA256"]="40507fac72e137d453d9638deddc9f083ee9fe89edba767da3c8c1c4598bb918",["Text"]="-----------------------------------\n-- The Cold Light of Day\n-----------------------------------\n-- Log ID: 1, Quest ID: 11\n-- Malene : !pos -173 -5 64 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_COLD_LIGHT_OF_DAY)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 500,\n    title    = xi.title.CRAB_CRUSHER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Malene'] = quest:progressEvent(102),\n\n            onEventFinish =\n            {\n                [102] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gwill'] = quest:event(103),\n\n            ['Malene'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.STEAM_CLOCK, 1 } }) then\n                        return quest:progressEvent(104)\n                    end\n                end,\n\n                onTrigger = quest:event(102),\n            },\n\n            onEventFinish =\n            {\n                [104] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Curse_Collector.lua"]={["Path"]="scripts/quests/bastok/The_Curse_Collector.lua",["SHA256"]="074415cfb3939a785e50233779c8f44c83e876795a876fbf2ba09b13b334cd35",["Text"]="-----------------------------------\n-- The Curse Collector\n-----------------------------------\n-- Log ID: 1, Quest ID: 34\n-- Zon-Fobun : !pos -241.293 -3 63.406 235\n-- The Mute  : !pos -166.230 -1 -73.685 147\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_CURSE_COLLECTOR)\n\nquest.reward =\n{\n    fame     = 40,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.POISON_CESTI,\n}\n\nlocal handleAfflictorTriggerArea = function(player, triggerArea)\n    local triggerAreaId = triggerArea:getTriggerAreaID()\n    local yPos          = player:getYPos()\n    local requiredYPos  = nil\n\n    if triggerAreaId == 4 then\n        requiredYPos = 35\n    elseif triggerAreaId >= 3 then\n        requiredYPos = 20\n    end\n\n    if\n        (not requiredYPos or\n        yPos > requiredYPos) and\n        not quest:isVarBitsSet(player, 'Prog', 1)\n    then\n        quest:setVarBit(player, 'Prog', 1)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getFameLevel(xi.fameArea.BASTOK) >= 4\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Zon-Fobun'] = quest:progressEvent(251),\n\n            onEventFinish =\n            {\n                [251] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CURSEPAPER)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Zon-Fobun'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: Determine if there is reminder dialogue prior to quest\n                    -- being completed.\n\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(252)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [252] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.CURSEPAPER)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BEADEAUX] =\n        {\n            ['The_Mute'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Prog', 0) then\n                        quest:setVarBit(player, 'Prog', 0)\n                    end\n\n                    -- Intentional Fallthrough\n                    -- TODO: Determine if there is a separate event or\n                    -- message displayed here.\n                end,\n            },\n\n            onTriggerAreaEnter =\n            {\n                [1] = handleAfflictorTriggerArea,\n                [2] = handleAfflictorTriggerArea,\n                [3] = handleAfflictorTriggerArea,\n                [4] = handleAfflictorTriggerArea,\n                [5] = handleAfflictorTriggerArea,\n                [6] = handleAfflictorTriggerArea,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Darksmith.lua"]={["Path"]="scripts/quests/bastok/The_Darksmith.lua",["SHA256"]="c6c7ea70d8182e91d179d9984259098c91412dd1e33ef3f1d4cb6420d2fe64fc",["Text"]="-----------------------------------\n-- The Darksmith\n-----------------------------------\n-- Log ID: 1, Quest ID: 40\n-- Mighty Fist : !pos -47 2 -30 237\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_DARKSMITH)\n\nquest.reward =\n{\n    fame     = 16,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 8000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Mighty_Fist'] = quest:progressEvent(565),\n\n            onEventFinish =\n            {\n                [565] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Mighty_Fist'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.CHUNK_OF_DARKSTEEL_ORE, 2 } }) then\n                        return quest:progressEvent(566)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if not quest:getMustZone(player) then\n                        return quest:event(561) -- First trigger only. Reset on zone.\n                    else\n                        return quest:event(560) -- Subsequent triggers.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [561] = function(player, csid, option, npc)\n                    quest:setMustZone(player)\n                end,\n\n                [566] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Elevenths_Hour.lua"]={["Path"]="scripts/quests/bastok/The_Elevenths_Hour.lua",["SHA256"]="e37d53a86b431b6b9b9b7278052d2c08f53af4f2caa756b6a61b27bdb2c2d0a2",["Text"]="-----------------------------------\n-- The Eleventh's Hour\n-----------------------------------\n-- Log ID: 1, Quest ID: 7\n-- Babenn      : !pos 73 -1 34 234\n-- Elki        : !pos -17.087 -0.05 52.745 234\n-- Old Toolbox : !pos 113.649 -32.8 79.617 143\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_ELEVENTHS_HOUR)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SMALL_SWORD,\n    title    = xi.title.PURSUER_OF_THE_TRUTH,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.HEARTS_OF_MYTHRIL) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3 and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Elki'] = quest:progressEvent(43),\n\n            onEventFinish =\n            {\n                [43] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Babenn'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(45)\n                    end\n                end,\n            },\n\n            ['Elki'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.OLD_TOOLBOX) then\n                        return quest:progressEvent(44)\n                    end\n                end,\n            },\n\n            ['Parraggoh'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_ELEVENTHS_HOUR) then\n                        return quest:event(46)\n                    end\n                end,\n            },\n\n            ['Pavvke'] = quest:event(48),\n\n            onEventFinish =\n            {\n                [44] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [45] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.OLD_TOOLBOX)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PALBOROUGH_MINES] =\n        {\n            ['Old_Toolbox'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.OLD_TOOLBOX) then\n                        return quest:progressEvent(23)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [23] = function(player, csid, option, npc)\n                    if option == 0 then\n                        player:addKeyItem(xi.keyItem.OLD_TOOLBOX)\n                    end\n                end\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Elvaan_Goldsmith.lua"]={["Path"]="scripts/quests/bastok/The_Elvaan_Goldsmith.lua",["SHA256"]="4535888dbd0633cf33218e2fcf8260215a02545d2518584fd2d2622f59ac7bd0",["Text"]="-----------------------------------\n-- The Elvaan Goldsmith\n-----------------------------------\n-- Log ID: 1, Quest ID: 13\n-- Michea : !pos -298 -16 -157 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_ELVAAN_GOLDSMITH)\n\nquest.reward =\n{\n    fame     = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 180,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Michea'] = quest:progressEvent(215),\n\n            onEventFinish =\n            {\n                [215] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED or\n                (\n                    status == xi.questStatus.QUEST_COMPLETED and\n                    player:getFameLevel(xi.fameArea.BASTOK) == 1 and\n                    not quest:getMustZone(player)\n                )\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Michea'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.COPPER_INGOT, 1 } }) then\n                        return quest:progressEvent(216)\n                    end\n                end,\n\n                onTrigger = quest:event(215),\n            },\n\n            onEventFinish =\n            {\n                [216] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        quest:setMustZone(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Gustaberg_Tour.lua"]={["Path"]="scripts/quests/bastok/The_Gustaberg_Tour.lua",["SHA256"]="5059e5cfe4618b9f2bf76d77406a62864f32623ed1228fe3ee9b16e4b964e493",["Text"]="-----------------------------------\n-- The Gustaberg Tour\n-----------------------------------\n-- Log ID      : 1, Quest ID: 45\n-- Izabele     : !pos -43.9 -10 -2.4 237\n-- Hunting Bear: !pos -235.7 40 424.5 106\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_GUSTABERG_TOUR)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 500,\n    title    = xi.title.GUSTABERG_TOURIST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Izabele'] = quest:progressEvent(745),\n\n            onEventFinish =\n            {\n                [745] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Izabele'] = quest:progressEvent(746)\n        },\n\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            ['Hunting_Bear'] =\n            {\n                onTrigger = function(player, npc)\n                    local flag = true\n\n                    for _, member in pairs(player:getAlliance()) do\n                        if\n                            member:getMainLvl() > 15 or\n                            member:checkDistance(player) > 15\n                        then\n                            flag = false\n                        end\n                    end\n\n                    if flag and #player:getParty() > 1 then\n                        return quest:progressEvent(22)\n                    else\n                        return quest:progressEvent(21)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [22] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Izabele'] = quest:event(747):replaceDefault()\n        },\n        [xi.zone.NORTH_GUSTABERG] =\n        {\n            ['Hunting_Bear'] = quest:event(23):replaceDefault()\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Quadavs_Curse.lua"]={["Path"]="scripts/quests/bastok/The_Quadavs_Curse.lua",["SHA256"]="07dcc416d187aef6f024be6148e0677db36dd977e6911fc90e32d66ba6fad0bf",["Text"]="-----------------------------------\n-- The Quadav's Curse\n-----------------------------------\n-- Log ID: 1, Quest ID: 4\n-- Corann : !pos 90.935 -8.772 32.564 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_QUADAVS_CURSE)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.BRONZE_SUBLIGAR,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Corann'] = quest:progressEvent(80),\n\n            onEventFinish =\n            {\n                [80] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Corann'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.QUADAV_BACKPLATE, 1 } }) then\n                        return quest:progressEvent(81)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [81] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.OUT_OF_ONES_SHELL)\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Corann'] = quest:event(87):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Return_of_the_Adventurer.lua"]={["Path"]="scripts/quests/bastok/The_Return_of_the_Adventurer.lua",["SHA256"]="97c9cf9b9cc60d8d3ab1865adff58139e94a22bacb5a165b8a615c77a6954f27",["Text"]="-----------------------------------\n-- The Return of the Adventurer\n-----------------------------------\n-- Log ID: 1, Quest ID: 30\n-- Gwill : !pos -317.829 -15.948 -177.375 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_RETURN_OF_THE_ADVENTURER)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.COTTON_HEADBAND,\n    title    = xi.title.KULATZ_BRIDGE_COMPANION,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.FATHER_FIGURE) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gwill'] = quest:progressEvent(242),\n\n            onEventFinish =\n            {\n                [242] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gwill'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.STICK_OF_CINNAMON, 1 } }) then\n                        return quest:progressEvent(243)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [243] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Signpost_Marks_the_Spot.lua"]={["Path"]="scripts/quests/bastok/The_Signpost_Marks_the_Spot.lua",["SHA256"]="cc2f5b3531b0d13b178eacd1da4b0725c67035bcb6b541b08806ea3da259a117",["Text"]="-----------------------------------\n-- The Signpost Marks the Spot\n-----------------------------------\n-- Log ID: 1, Quest ID: 22\n-- Nbu Latteh : !pos -114.777 -4 -113.301 235\n-- Roh Latteh : !pos -11.823 6.999 -9.249 234\n-- Signpost   : !pos -183 65 599 108\n-----------------------------------\nlocal konschtatID = zones[xi.zone.KONSCHTAT_HIGHLANDS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_SIGNPOST_MARKS_THE_SPOT)\n\nquest.reward =\n{\n    item     = xi.item.LINEN_ROBE,\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    title    = xi.title.TREASURE_SCAVENGER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2 and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.MOM_THE_ADVENTURER) and\n                not xi.quest.getMustZone(player, xi.questLog.BASTOK, xi.quest.id.bastok.MOM_THE_ADVENTURER)\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Nbu_Latteh'] = quest:progressEvent(235),\n\n            onEventFinish =\n            {\n                [235] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.KONSCHTAT_HIGHLANDS] =\n        {\n            ['Signpost3'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.PAINTING_OF_A_WINDMILL) then\n                        player:messageSpecial(konschtatID.text.SIGNPOST3_DIALOG_2)\n\n                        return quest:keyItem(xi.keyItem.PAINTING_OF_A_WINDMILL)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Roh_Latteh'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.PAINTING_OF_A_WINDMILL) then\n                        return quest:progressEvent(96)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [96] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.PAINTING_OF_A_WINDMILL)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Sirens_Tear.lua"]={["Path"]="scripts/quests/bastok/The_Sirens_Tear.lua",["SHA256"]="3b5e859a5882d3e2a37420a0d3ff91d103ce48e786a1fa7d41de9be472877d4d",["Text"]="-----------------------------------\n-- The Siren's Tear\n-----------------------------------\n-- Log ID: 1, Quest ID: 0\n-- Wahid       : !pos 26.305 -1 -66.403 234\n-- Otto        : !pos -145.929 -7.48 13.701 236\n-- Carmelo     : !pos -146.476 -7.48 -10.889 236\n-- Echo Hawk   : !pos -0.965 5.999 -15.567 234\n-- qm1 (moves) : !pos 309.6 2.6 324 106\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_SIRENS_TEAR)\n\nquest.reward =\n{\n    fame = 10,\n    fameArea = xi.fameArea.BASTOK,\n    gil = 150,\n    title = xi.title.TEARJERKER,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Wahid']     = quest:progressEvent(81),\n            ['Echo_Hawk'] = quest:event(5),\n\n            onEventFinish =\n            {\n                [81] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Otto'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(5)\n                    end\n                end,\n            },\n\n            ['Carmelo'] = quest:progressEvent(6),\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Carmelo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') < 2 and\n                        not player:findItem(xi.item.SIRENS_TEAR)\n                    then\n                        return quest:progressEvent(19)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [19] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Section accepted or completed\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Wahid'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.SIRENS_TEAR, 1 } }) then\n                        return quest:progressEvent(82)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [82] = function(player, csid, option, npc)\n                    -- This is called even after the initial complete to handle quest var cleanup\n                    -- CLuaBaseEntity::completeQuest() will only actually complete the quest the\n                    -- first time the player finishes this.\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Stars_of_Ifrit.lua"]={["Path"]="scripts/quests/bastok/The_Stars_of_Ifrit.lua",["SHA256"]="ee68f5383e15ee274287139f1a0d0097a945086c5dcd25e559f7131f8cb8ea28",["Text"]="-----------------------------------\n-- The Stars of Ifrit\n-----------------------------------\n-- Log ID: 1, Quest ID: 42\n-- Agapito : !pos -72.093 -3.097 9.309 236\n-- qm1     : !pos -9 -5 -13 223\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_STARS_OF_IFRIT)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 2100,\n    title    = xi.title.STAR_OF_IFRIT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasKeyItem(xi.keyItem.AIRSHIP_PASS) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Agapito'] = quest:progressEvent(180),\n\n            onEventFinish =\n            {\n                [180] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Agapito'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.CARRIER_PIGEON_LETTER) then\n                        return quest:progressEvent(181)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [181] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.SAN_DORIA_JEUNO_AIRSHIP] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    -- NOTE: Visibility of this NPC is limited to Full Moon and Night Time,\n                    -- and is handled in onGameHour in Zone.lua for San d'Oria-Jeuno Airship.\n                    -- This is a permanent Key Item.\n\n                    if not player:hasKeyItem(xi.keyItem.CARRIER_PIGEON_LETTER) then\n                        return quest:keyItem(xi.keyItem.CARRIER_PIGEON_LETTER)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Usual.lua"]={["Path"]="scripts/quests/bastok/The_Usual.lua",["SHA256"]="a5a151a268cdab33f21921ba46786364edccb25cd9bfadb4508fccb73f83992f",["Text"]="-----------------------------------\n-- The Usual\n-----------------------------------\n-- Log ID: 1, Quest ID: 27\n-- Hilda   : !pos -163 -8 13 236\n-- Raibaht : !pos -27 -10 -1 237\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_USUAL)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SPEED_BOW,\n    title    = xi.title.STEAMING_SHEEP_REGULAR,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.CIDS_SECRET) and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 5\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Hilda'] = quest:progressEvent(134),\n\n            onEventFinish =\n            {\n                [134] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Hilda'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasKeyItem(xi.keyItem.STEAMING_SHEEP_INVITATION) and\n                        npcUtil.tradeMatches(trade, { { xi.item.KING_TRUFFLE, 1 } })\n                    then\n                        return quest:progressEvent(135)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(136)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [135] = function(player, csid, option, npc)\n                    player:tradeComplete()\n\n                    npcUtil.giveKeyItem(player, xi.keyItem.STEAMING_SHEEP_INVITATION)\n                end,\n\n                [136] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.STEAMING_SHEEP_INVITATION)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Raibaht'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.STEAMING_SHEEP_INVITATION) and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        return quest:progressEvent(510)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [510] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Walls_of_Your_Mind.lua"]={["Path"]="scripts/quests/bastok/The_Walls_of_Your_Mind.lua",["SHA256"]="eea8b9d29acd277a107fb4deb59df667ae2e4fea1c611655a2e1f494a3958c65",["Text"]="-----------------------------------\n-- The Walls of Your Mind\n-- Oggbi !pos -159 -7 5 236\n-- qm1 !pos 20 17 -140 167\n-----------------------------------\nlocal portBastokID = zones[xi.zone.PORT_BASTOK]\nlocal bostaunieuxID = zones[xi.zone.BOSTAUNIEUX_OUBLIETTE]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_WALLS_OF_YOUR_MIND)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.KNUCKLES_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.HAND_TO_HAND) / 10 >= 250 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Oggbi'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(286):oncePerZone() -- Start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [286] = function(player, csid, option, npc)\n                    if\n                        player:hasItem(xi.item.KNUCKLES_OF_TRIALS) or\n                        npcUtil.giveItem(player, xi.item.KNUCKLES_OF_TRIALS)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Oggbi'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(290)\n                    else\n                        local hideReacquireMenuItem = (player:hasItem(xi.item.KNUCKLES_OF_TRIALS) or player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)) and 1 or 0\n                        return quest:event(287, hideReacquireMenuItem)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.KNUCKLES_OF_TRIALS, 1 } }) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(288)\n                        else\n                            return quest:progressEvent(289)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [287] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.KNUCKLES_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.KNUCKLES_OF_TRIALS)\n                    elseif option == 2 then\n                        player:delQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_WALLS_OF_YOUR_MIND)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [289] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [290] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.ASURAN_FISTS)\n                        player:messageSpecial(portBastokID.text.ASURAN_FISTS_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BOSTAUNIEUX_OUBLIETTE] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, bostaunieuxID.mob.BODACH, { hide = 0 })\n                    then\n                        return quest:messageSpecial(bostaunieuxID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Bodach'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Weight_of_Your_Limits.lua"]={["Path"]="scripts/quests/bastok/The_Weight_of_Your_Limits.lua",["SHA256"]="b5cf477ff035b4d5eac0cd16e6a499f2c95c4558e8fc3760632de98dce4490cd",["Text"]="-----------------------------------\n-- The Weight of Your Limits\n-- Iron Eater !pos 92 -19.6 2 237\n-- qm1 !pos -324 1 474 121\n-----------------------------------\nlocal metalworksID = zones[xi.zone.METALWORKS]\nlocal ziTahID      = zones[xi.zone.THE_SANCTUARY_OF_ZITAH]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_WEIGHT_OF_YOUR_LIMITS)\n\nquest.reward =\n{\n    fame = 20,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:canEquipItem(xi.item.AXE_OF_TRIALS, true) and\n                player:getCharSkillLevel(xi.skill.GREAT_AXE) / 10 >= 240 and\n                not player:hasKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Iron_Eater'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(790):oncePerZone() -- start\n                end,\n            },\n\n            onEventFinish =\n            {\n                [790] = function(player, csid, option, npc)\n                    if\n                        player:hasItem(xi.item.AXE_OF_TRIALS) or\n                        npcUtil.giveItem(player, xi.item.AXE_OF_TRIALS)\n                    then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Iron_Eater'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) then\n                        return quest:progressEvent(794) -- complete\n                    else\n                        local hideReacquireMenuItem = (player:hasItem(xi.item.AXE_OF_TRIALS) or player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)) and 1 or 0\n                        return quest:event(791, hideReacquireMenuItem) -- cont 1\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.AXE_OF_TRIALS, 1 } }) then\n                        local wsPoints = trade:getItem(0):getWeaponskillPoints()\n\n                        if wsPoints < 300 then\n                            return quest:event(792) -- unfinished weapon\n                        else\n                            return quest:progressEvent(793) -- finished weapon\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [791] = function(player, csid, option, npc)\n                    if option == 1 and not player:hasItem(xi.item.AXE_OF_TRIALS) then\n                        npcUtil.giveItem(player, xi.item.AXE_OF_TRIALS)\n                    elseif option == 2 then\n                        player:delQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_WEIGHT_OF_YOUR_LIMITS)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                    end\n                end,\n\n                [793] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                end,\n\n                [794] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                        player:delKeyItem(xi.keyItem.WEAPON_TRAINING_GUIDE)\n                        player:addLearnedWeaponskill(xi.wsUnlock.STEEL_CYCLONE)\n                        player:messageSpecial(metalworksID.text.STEEL_CYCLONE_LEARNED)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.THE_SANCTUARY_OF_ZITAH] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('killed_wsnm') == 1 then\n                        player:setLocalVar('killed_wsnm', 0)\n                        return quest:keyItem(xi.keyItem.ANNALS_OF_TRUTH)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) and\n                        not player:hasKeyItem(xi.keyItem.ANNALS_OF_TRUTH) and\n                        npcUtil.popFromQM(player, npc, ziTahID.mob.GREENMAN, { hide = 0 })\n                    then\n                        return quest:messageSpecial(ziTahID.text.SENSE_OMINOUS_PRESENCE)\n                    end\n                end,\n            },\n\n            ['Greenman'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if player:hasKeyItem(xi.keyItem.MAP_TO_THE_ANNALS_OF_TRUTH) then\n                        player:setLocalVar('killed_wsnm', 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/The_Wisdom_of_Elders.lua"]={["Path"]="scripts/quests/bastok/The_Wisdom_of_Elders.lua",["SHA256"]="57cbb5e3e107458194dccbf6e321c3d53624e4e876b817489059b95582095d3b",["Text"]="-----------------------------------\n-- The Wisdom of Elders\n-----------------------------------\n-- Log ID: 1, Quest ID: 36\n-- Benita : !pos 49.692 -4.771 36.189 236\n-- Tete   : !pos 15.249 -2.097 43.012 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_WISDOM_OF_ELDERS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.TRAVELERS_HAT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Benita'] = quest:progressEvent(174),\n\n            onEventFinish =\n            {\n                [174] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Benita'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.PINCH_OF_BOMB_ASH, 1 } }) then\n                        return quest:progressEvent(176)\n                    end\n                end,\n            },\n\n            ['Tete'] = quest:event(175):importantOnce(),\n\n            onEventFinish =\n            {\n                [175] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [176] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
